use std::fs
use std::collections::BTreeMap

fn amount_of(s: string) -> int {
    s.parse::<int>().unwrap_or(0)
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut acc: BTreeMap<string, int> = BTreeMap::new()
    for line in text.lines() {
        let p: Vec<string> = line.split_whitespace().collect()
        if p.len() == 0 {
            continue
        }
        let cmd = p[0]
        if cmd == "open" && p.len() >= 3 {
            let a: int = amount_of(p[2])
            if a < 0 {
                println("error: invalid amount")
            } else if acc.contains_key(p[1]) {
                println("error: duplicate account")
            } else {
                acc.insert(p[1], a)
                println("ok")
            }
        } else if cmd == "balance" && p.len() >= 2 {
            if acc.contains_key(p[1]) {
                let b: int = acc[p[1]]
                println("${b}")
            } else {
                println("error: unknown account ${p[1]}")
            }
        } else if (cmd == "deposit" || cmd == "withdraw") && p.len() >= 3 {
            let a: int = amount_of(p[2])
            if a <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(p[1]) {
                println("error: unknown account ${p[1]}")
            } else {
                let b: int = acc[p[1]]
                if cmd == "deposit" {
                    acc.insert(p[1], b + a)
                    println("ok")
                } else if b < a {
                    println("error: insufficient funds")
                } else {
                    acc.insert(p[1], b - a)
                    println("ok")
                }
            }
        } else if cmd == "transfer" && p.len() >= 4 {
            let a: int = amount_of(p[3])
            if a <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(p[1]) {
                println("error: unknown account ${p[1]}")
            } else if !acc.contains_key(p[2]) {
                println("error: unknown account ${p[2]}")
            } else if p[1] == p[2] {
                println("error: same account")
            } else {
                let fb: int = acc[p[1]]
                let tb: int = acc[p[2]]
                if fb < a {
                    println("error: insufficient funds")
                } else {
                    acc.insert(p[1], fb - a)
                    acc.insert(p[2], tb + a)
                    println("ok")
                }
            }
        }
    }
    for (k, v) in acc {
        println("${k} ${v}")
    }
}

